const cmds = [
  ["pwd + status", "pwd; git status --short", "."],
  ["tag counts", "rg -n '\\\\provenancetag\\{|TO CHECK|tocheck|to-check' blueprint/src/chapters | wc -l; rg -o '\\\\provenancetag\\{(REFERENCE|ADAPTED|CUSTOM)\\}' blueprint/src/chapters | sort | uniq -c", "."],
  ["chapter files", "rg --files blueprint/src/chapters | sort", "."],
  ["live diff stat", "git diff --stat -- blueprint/src/chapters blueprint/src/*.tex AlgebraicJacobian/Challenge.lean", "."]
];
const out = await Promise.all(cmds.map(async ([label, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:3000});
  return `## ${label}\n${r.output}`;
}));
text(out.join("\n"));

const r = await tools.exec_command({
  cmd: "rg -n '\\\\newcommand\\{\\\\source|source\\{|provenancetag|begin\\{(definition|lemma|theorem|proposition|corollary|remark)' blueprint/src | head -80",
  workdir: ".",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const qs = [
  ["adaptation prose", "rg -n -i 'adapt|strengthen|weaker|stronger|not assumed|without (the )?(Noetherian|genus)|in contrast|differs|variation|generaliz|specializ|reformulat|instead of|does not directly|not quite|slightly' blueprint/src/chapters"],
  ["source caveats", "rg -n -i 'reference|source|Milne|Kleiman|Hartshorne|Mumford|Nitsure|Papaioannou|Stacks' blueprint/src/chapters | rg -i 'only|but|however|assum|scope|page|argument|proof|uses|does not|not'"],
  ["unproved/check language", "rg -n -i 'unproved|gap|pending|TODO|FIXME|open obligation|not yet|missing|unsound|mismatch|scope' blueprint/src/chapters"]
];
const out = await Promise.all(qs.map(async ([label, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:".", yield_time_ms:10000, max_output_tokens:20000});
  return `## ${label}\n${r.output}`;
}));
text(out.join("\n"));

