   534	\section{The Abel source: properness and geometric irreducibility}
   535	\label{sec:abel_source}
   536	
   537	\begin{definition}[Abel source]
   538	  \label{def:abel_source}
   539	  \lean{AlgebraicGeometry.AbelSourceData}
   540	  \uses{def:jacobian_data}
   541	  \leanok
   542	  Let \(d\) be a Jacobian datum with representing object \(J\). An
   543	  \emph{Abel source} for \(d\) consists of:
   544	  \begin{enumerate}
   545	    \item a scheme \(D\) over \(k\);
   546	    \item a certificate that \(D\) is proper over \(k\);
   547	    \item a certificate that \(D\) is geometrically irreducible over \(k\);
   548	    \item an \emph{Abel morphism} \(a : D \to J\) over \(k\);
   549	    \item a certificate that \(a\) is surjective on underlying topological
   550	      spaces.
   551	  \end{enumerate}
   552	  This is a conditional interface: its definition asserts neither the
   553	  existence of \(D\) nor the existence of \(a\). The intended instance takes
   554	  \(D\) to be a proper scheme of effective divisors of large degree on \(C\)
   555	  and \(a\) to be the Abel map.
   556	\end{definition}
   557	
   558	\begin{theorem}[The representing object is universally closed]
   559	  \label{thm:jacobianData_universallyClosed}
   560	  \lean{AlgebraicGeometry.universallyClosed_of_abelSource}
   561	  \uses{def:abel_source, def:jacobian_data}
   562	  \leanok
   563	  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
   564	  morphism of the representing object \(J\) is universally closed.
   565	\end{theorem}
   566	\begin{proof}
   567	  \leanok
   568	  Let \(a : D \to J\) be the Abel morphism. Since \(a\) is a morphism over
   569	  \(k\), the composite of \(a\) with the structure morphism of \(J\) is the
   570	  structure morphism of \(D\), which is universally closed (\(D\) is proper).
   571	  Surjectivity and closedness are stable under base change, so it suffices to
   572	  see: if \(g \circ f\) is universally closed and \(f\) is surjective, then
   573	  \(g\) is universally closed. Indeed, after any base change, for a closed
   574	  subset \(Z\) of the source of the (base-changed) \(g'\),
   575	  \(g'(Z) = (g' \circ f')\bigl(f'^{-1}(Z)\bigr)\) by surjectivity of the
   576	  base-changed \(f'\), and the right-hand side is closed since
   577	  \(g' \circ f' = (g \circ f)'\) is a closed map.
   578	\end{proof}
   579	
   580	\begin{theorem}[The representing object is proper]
   581	  \label{thm:jacobianData_proper}
   582	  \lean{AlgebraicGeometry.isProper_of_abelSource}
   583	  \uses{def:abel_source, cor:jacobianData_separated,
   584	    thm:jacobianData_universallyClosed, def:jacobian_data}
   585	  \leanok
   586	  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
   587	  morphism of the representing object \(J\) is proper.
   588	\end{theorem}
   589	\begin{proof}
   590	  \leanok
   591	  Properness is the conjunction of separatedness, universal closedness and
   592	  finite type. Separatedness is \ref{cor:jacobianData_separated}; universal
   593	  closedness is \ref{thm:jacobianData_universallyClosed}; the structure morphism
   594	  is locally of finite type by the datum's certificate
   595	  (\ref{def:jacobian_data}), and quasi-compact because universally closed
   596	  morphisms are quasi-compact; locally of finite type and quasi-compact is
   597	  finite type.
   598	\end{proof}
   599	
   600	\begin{theorem}[The representing object is geometrically irreducible]
   601	  \label{thm:jacobianData_geomIrreducible}
   602	  \lean{AlgebraicGeometry.geometricallyIrreducible_of_abelSource}
   603	  \uses{def:abel_source}
   604	  \leanok
   605	  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
   606	  morphism of the representing object \(J\) is geometrically irreducible: for
   607	  every field extension \(K/k\), the base change \(J_K\) is irreducible.
   608	\end{theorem}
   609	\begin{proof}
   610	  \leanok
   611	  Fix a field extension \(K/k\) and a fibre product \(Z = J \times_k K\) with
   612	  projections to \(J\) and \(\Spec K\). The base change
   613	  \(D_K = D \times_k K\) is irreducible by the Abel source's certificate. The
   614	  comparison morphism \(D_K \to Z\) induced by the Abel morphism \(a\) is,
